-- Refresh skill add-on effect catalog (idempotent).
-- Source of truth: data/codex/skill_addon_effects.json (also seeded in 018_morphs.sql).
-- Regenerated by: npx tsx scripts/build-codex-seed.ts

on conflict (key) do update set
  name_ru = excluded.name_ru,
  effect_group = excluded.effect_group,
  tier_labels = excluded.tier_labels,
  sort_order = excluded.sort_order,
  updated_at = now();
